# static_html.py -- Kompakte Single Page App (Fallback)

HTML_PAGE = '<!DOCTYPE html>\n<html lang="de">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>signalrpi Gateway</title>\n<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 100 100\'%3E%3Crect width=\'100\' height=\'100\' rx=\'22\' fill=\'%230f172a\'/%3E%3Cpath d=\'M30 68 C30 52 42 40 58 40 M30 80 C30 58 48 40 70 40\' stroke=\'%2338bdf8\' stroke-width=\'7\' stroke-linecap=\'round\' fill=\'none\'/%3E%3Cpath d=\'M25 55 C25 35 40 20 65 20 M25 42 C25 22 45 10 75 10\' stroke=\'%2338bdf8\' stroke-width=\'7\' stroke-linecap=\'round\' fill=\'none\' opacity=\'0.7\'/%3E%3Ccircle cx=\'30\' cy=\'75\' r=\'7\' fill=\'%2338bdf8\'/%3E%3C/svg%3E">\n<style>\n:root{--bg:#0f172a;--card:rgba(30,41,59,0.7);--border:rgba(255,255,255,0.1);--accent:#38bdf8;--text:#f8fafc;--text-dim:#94a3b8;--green:#22c55e;--red:#ef4444;--amber:#f59e0b}\n*{box-sizing:border-box;margin:0;padding:0;font-family:system-ui,-apple-system,sans-serif}\nbody{background:var(--bg);color:var(--text);padding:1rem;min-height:100vh}\n.header{display:flex;justify-content:space-between;align-items:center;padding:0.75rem 1.25rem;background:var(--card);backdrop-filter:blur(12px);border:1px solid var(--border);border-radius:12px;margin-bottom:1rem}\n.brand{font-size:1.25rem;font-weight:700;color:var(--accent);display:flex;align-items:center;gap:8px}\n.pill{background:rgba(34,197,94,0.2);color:var(--green);padding:4px 10px;border-radius:20px;font-size:0.8rem;font-weight:600}\n.nav{display:flex;gap:8px;margin-bottom:1rem}\n.nav-btn{background:var(--card);border:1px solid var(--border);color:var(--text-dim);padding:8px 16px;border-radius:8px;cursor:pointer;font-weight:600}\n.nav-btn.active{background:var(--accent);color:#0f172a}\n.card{background:var(--card);border:1px solid var(--border);backdrop-filter:blur(12px);border-radius:12px;padding:1.25rem;margin-bottom:1rem}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1rem}\n.device-card{background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px}\n.val-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}\n.val-box{background:rgba(255,255,255,0.03);padding:8px;border-radius:6px;border:1px solid rgba(255,255,255,0.05)}\n.val-title{font-size:0.75rem;color:var(--text-dim)}\n.val-num{font-size:1.15rem;font-weight:700;color:var(--accent)}\n.btn{background:var(--accent);color:#0f172a;border:none;padding:6px 12px;border-radius:6px;font-weight:600;cursor:pointer}\n.btn-amber{background:var(--amber);color:#0f172a}\n.btn-del{background:var(--red);color:#fff}\n.sniffer-box{max-height:500px;overflow-y:auto;font-family:monospace;font-size:0.85rem}\n.packet{padding:10px 12px;border-bottom:1px solid rgba(255,255,255,0.06);display:flex;justify-content:space-between;align-items:center;gap:12px}\n.packet:hover{background:rgba(255,255,255,0.02)}\n.form-input{width:100%;padding:8px;background:rgba(15,23,42,0.8);border:1px solid var(--border);color:#fff;border-radius:6px;margin:6px 0 12px}\n.modal{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);backdrop-filter:blur(4px);justify-content:center;align-items:center;z-index:100}\n.modal-card{background:#1e293b;border:1px solid var(--border);padding:1.5rem;border-radius:12px;width:90%;max-width:400px}\n.toast-container{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:999;display:flex;flex-direction:column;gap:8px;pointer-events:none}\n.toast{background:rgba(15,23,42,0.92);backdrop-filter:blur(12px);border:1px solid var(--border);color:var(--text);padding:10px 18px;border-radius:10px;font-size:0.875rem;font-weight:500;box-shadow:0 10px 25px -5px rgba(0,0,0,0.5);display:flex;align-items:center;gap:10px;animation:toastIn 0.3s cubic-bezier(0.16,1,0.3,1);transition:opacity 0.3s, transform 0.3s}\n.toast.toast-success{border-color:rgba(34,197,94,0.4);color:#bbf7d0}\n.toast.toast-error{border-color:rgba(239,68,68,0.4);color:#fecaca}\n.toast.toast-info{border-color:rgba(56,189,248,0.4);color:#bae6fd}\n@keyframes toastIn{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}\n</style>\n</head>\n<body>\n<div class="header">\n  <div class="brand">📻 signalrpi Gateway</div>\n  <div style="display:flex;align-items:center;gap:8px">\n    <div class="pill" id="badge-cc433" style="background:rgba(255,255,255,0.05);color:var(--text-dim)">433 MHz: ...</div>\n    <div class="pill" id="badge-cc868" style="background:rgba(255,255,255,0.05);color:var(--text-dim)">868 MHz: ...</div>\n    <div class="pill" id="sys-status">WLAN</div>\n  </div>\n</div>\n<div class="nav">\n  <button class="nav-btn active" onclick="showTab(\'tab-devices\')">Geräte</button>\n  <button class="nav-btn" onclick="showTab(\'tab-sniffer\')">Live Sniffer</button>\n  <button class="nav-btn" onclick="showTab(\'tab-it\')">Intertechno</button>\n  <button class="nav-btn" onclick="showTab(\'tab-system\')">System</button>\n</div>\n\n<div id="tab-devices" class="tab-content">\n  <div class="card">\n    <div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-bottom:1.25rem">\n      <div>\n        <h3 style="margin-bottom:2px">Bekannte Funk-Geräte</h3>\n        <p style="color:var(--text-dim);font-size:0.8rem">Übersicht aller im Gateway gespeicherten Sensoren und Aktoren.</p>\n      </div>\n      <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center">\n        <label style="font-size:0.8rem;color:var(--text-dim)">Gruppierung:</label>\n        <select id="device-grouping-select" class="form-input" style="width:auto;margin:0;padding:5px 8px;font-size:0.8rem" onchange="renderDevices()">\n          <option value="none">Keine (Kompakt)</option>\n          <option value="protocol">Nach Funk-Protokoll</option>\n          <option value="profile">Nach Geräte-Typ</option>\n          <option value="mqtt">Nach MQTT-Status</option>\n        </select>\n        <label style="font-size:0.8rem;color:var(--text-dim);margin-left:4px">Filter:</label>\n        <select id="device-filter-mqtt" class="form-input" style="width:auto;margin:0;padding:5px 8px;font-size:0.8rem" onchange="renderDevices()">\n          <option value="all">Alle Geräte</option>\n          <option value="mqtt_only">Nur mit MQTT</option>\n          <option value="no_mqtt">Nur ohne MQTT</option>\n        </select>\n      </div>\n    </div>\n    <div id="devices-list">Lade Geräte...</div>\n  </div>\n</div>\n\n<div id="tab-sniffer" class="tab-content" style="display:none">\n  <div class="card">\n    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem">\n      <div>\n        <h3>Live Funk-Sniffer</h3>\n        <p style="color:var(--text-dim);font-size:0.85rem">Empfängt Live-Signale von 433.92 MHz (OOK) und 868.35 MHz (FSK).</p>\n      </div>\n      <button class="btn" id="sniffer-toggle-btn" onclick="toggleSniffer()">Starten</button>\n    </div>\n    <div id="sniffer-list" class="sniffer-box">Klicke auf "Starten" um Signale zu empfangen...</div>\n  </div>\n</div>\n\n<div id="tab-it" class="tab-content" style="display:none">\n  <div class="card">\n    <h3>Intertechno Fernbedienung & Anlernen</h3>\n    <p style="color:var(--text-dim);font-size:0.85rem;margin:8px 0 16px">\n      Sende Funkbefehle zum Schalten oder Anlernen von Intertechno Funk-Steckdosen und Aktoren.\n    </p>\n\n    <div style="display:flex;gap:8px;margin-bottom:16px">\n      <button id="it-tab-btn-v3" class="btn" onclick="switchITSubTab(\'v3\')" style="background:var(--accent);color:#0f172a">V3 Selbstlernend (26-Bit)</button>\n      <button id="it-tab-btn-v1" class="btn" onclick="switchITSubTab(\'v1\')" style="background:transparent;color:var(--text-dim);border:1px solid var(--border)">V1 Klassisch DIP (Hauscode)</button>\n    </div>\n\n    <!-- V3 Selbstlernend -->\n    <div id="it-form-v3" style="max-width:460px">\n      <p style="color:var(--text-dim);font-size:0.85rem;margin:0 0 14px">\n        Intertechno V3 nutzt einen 26-Bit Rolling-/Zufalls-Binärcode. Erzeuge einen neuen kollisionsfreien Code für SignalRPI oder gib einen bestehenden Code ein.\n      </p>\n      \n      <label style="font-size:0.85rem;color:var(--text-dim)">Gerätename:</label>\n      <input id="it-v3-name" class="form-input" value="Küche Stehlampe" placeholder="z.B. Wohnzimmer Lampe">\n      \n      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px">\n        <label style="font-size:0.85rem;color:var(--text-dim)">26-Bit Sender Binärcode:</label>\n        <span id="it-v3-bitcount" style="font-size:0.75rem;color:var(--accent);font-family:monospace">26 / 26 Bit</span>\n      </div>\n      <input id="it-v3-bin" class="form-input" style="font-family:monospace;letter-spacing:1px;font-weight:600" value="00011100110111100110100111" maxlength="35" oninput="validateITV3Bits()" placeholder="26 Bit (0 und 1)">\n      <button class="btn" style="width:100%;margin-bottom:10px;background:rgba(59,130,246,0.2);color:var(--accent);border:1px solid rgba(59,130,246,0.4)" onclick="generateUniqueITV3Code()">🎲 Zufallscode generieren</button>\n\n      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:4px">\n        <label style="font-size:0.85rem;color:var(--text-dim)">Kanal / Unit (1..16):</label>\n        <span style="font-size:0.75rem;color:var(--text-dim)">Standard: 1</span>\n      </div>\n      <input id="it-v3-channel" class="form-input" type="number" value="1" min="1" max="16" style="margin-bottom:8px">\n\n      <label style="font-size:0.85rem;color:var(--text-dim)">Wiederholungen (Repetitions):</label>\n      <input id="it-v3-reps" class="form-input" type="number" value="6" min="1" max="25" style="margin-bottom:14px">\n\n      <input type="hidden" id="it-v3-edit-id" value="">\n\n      <div style="display:flex;flex-wrap:wrap;gap:8px">\n        <button id="it-v3-save-btn" class="btn" onclick="saveITV3Device()" style="background:var(--accent);color:#fff;font-weight:600">💾 Anlegen</button>\n        <button id="it-v3-cancel-btn" class="btn" style="display:none;background:#64748b;color:#fff" onclick="resetITV3Form()">Abbrechen</button>\n        <button class="btn" style="background:var(--green);color:#fff;font-weight:600" onclick="sendITV3Command(\'learn\')">📡 Anlernen</button>\n        <button class="btn" style="background:var(--green);color:#fff" onclick="sendITV3Command(\'on\')">EIN</button>\n        <button class="btn" style="background:var(--red);color:#fff" onclick="sendITV3Command(\'off\')">AUS</button>\n      </div>\n    </div>\n\n    <!-- V1 Klassisch DIP -->\n    <div id="it-form-v1" style="max-width:460px;display:none">\n      <p style="color:var(--text-dim);font-size:0.85rem;margin:0 0 14px">\n        Klassische Intertechno-Geräte mit DIP-Schaltern bzw. Kodierrädchen (Hauscode A..P, z.B. <code>E4</code>).\n      </p>\n      <label style="font-size:0.85rem;color:var(--text-dim)">Gerätename:</label>\n      <input id="it-name" class="form-input" value="Stehlampe">\n      <label style="font-size:0.85rem;color:var(--text-dim)">Hauscode (A..P):</label>\n      <input id="it-family" class="form-input" value="E" maxlength="1">\n      <label style="font-size:0.85rem;color:var(--text-dim)">Gruppe (1..4):</label>\n      <input id="it-group" class="form-input" type="number" value="1" min="1" max="4">\n      <label style="font-size:0.85rem;color:var(--text-dim)">Kanal (1..4):</label>\n      <input id="it-device" class="form-input" type="number" value="4" min="1" max="4" style="margin-bottom:8px">\n\n      <label style="font-size:0.85rem;color:var(--text-dim)">Wiederholungen (Repetitions):</label>\n      <input id="it-v1-reps" class="form-input" type="number" value="6" min="1" max="25" style="margin-bottom:14px">\n\n      <input type="hidden" id="it-v1-edit-id" value="">\n\n      <div style="display:flex;flex-wrap:wrap;gap:8px">\n        <button id="it-v1-save-btn" class="btn" onclick="saveITDevice()" style="background:var(--accent);color:#fff;font-weight:600">💾 Anlegen</button>\n        <button id="it-v1-cancel-btn" class="btn" style="display:none;background:#64748b;color:#fff" onclick="resetITV1Form()">Abbrechen</button>\n        <button class="btn" style="background:var(--green);color:#fff" onclick="sendITV1Command(\'on\')">EIN</button>\n        <button class="btn" style="background:var(--red);color:#fff" onclick="sendITV1Command(\'off\')">AUS</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div id="tab-system" class="tab-content" style="display:none">\n  <div class="card">\n    <h3>System Status & Diagnose</h3>\n    <div class="val-grid" style="max-width:500px;margin-top:1rem">\n      <div class="val-box"><div class="val-title">Systemzeit</div><div class="val-num" id="s-time">...</div></div>\n      <div class="val-box"><div class="val-title">IP-Adresse</div><div class="val-num" id="s-ip">...</div></div>\n      <div class="val-box"><div class="val-title">WLAN Signal</div><div class="val-num" id="s-rssi">...</div></div>\n      <div class="val-box"><div class="val-title">Freier RAM</div><div class="val-num" id="s-ram">...</div></div>\n    </div>\n  </div>\n\n  <div class="card">\n    <h3>📻 CC1101 Funk-Module Hardware-Diagnose</h3>\n    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem;margin-top:1rem">\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">\n          <h4 style="color:var(--accent)">Modul 1: 433 MHz</h4>\n          <span id="cc433-badge" class="pill" style="font-size:0.75rem">...</span>\n        </div>\n        <div style="font-size:0.85rem;color:var(--text-dim);line-height:1.6" id="cc433-details">Lade Details...</div>\n      </div>\n\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">\n          <h4 style="color:var(--accent)">Modul 2: 868 MHz</h4>\n          <span id="cc868-badge" class="pill" style="font-size:0.75rem">...</span>\n        </div>\n        <div style="font-size:0.85rem;color:var(--text-dim);line-height:1.6" id="cc868-details">Lade Details...</div>\n      </div>\n    </div>\n  </div>\n\n  <div class="card">\n    <h3>🔔 System-Meldungen & Alerts</h3>\n    <div id="system-alerts-list" style="max-height:220px;overflow-y:auto;font-family:monospace;font-size:0.8rem;margin-top:1rem;background:rgba(15,23,42,0.8);border:1px solid var(--border);border-radius:8px;padding:8px">\n      Keine aktuellen Warnungen.\n    </div>\n  </div>\n\n  <div class="card">\n    <h3>🕒 Datum, Uhrzeit & NTP-Zeitzone</h3>\n    <div style="max-width:420px;margin-top:1rem">\n      <label style="font-size:0.85rem;color:var(--text-dim)">Zeitzone / UTC-Offset (Stunden):</label>\n      <input id="tz-offset" class="form-input" type="number" value="1" min="-12" max="14">\n      <label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-size:0.85rem;margin:10px 0 16px">\n        <input type="checkbox" id="tz-auto-dst" checked style="width:16px;height:16px">\n        <span>Automatische Sommerzeit (EU-DST / MESZ)</span>\n      </label>\n      <label style="font-size:0.85rem;color:var(--text-dim)">Eigener NTP-Server (Optional):</label>\n      <input id="tz-server" class="form-input" type="text" placeholder="pool.ntp.org oder leer lassen" style="margin-bottom:16px">\n      <button class="btn" onclick="saveTimeSettings()">💾 Einstellungen speichern & Synchronisieren</button>\n      <div id="tz-status" style="font-size:0.85rem;margin-top:10px;color:var(--green)"></div>\n    </div>\n  </div>\n\n  <div class="card">\n    <h3>🚀 Firmware & OTA Updates</h3>\n    <p style="color:var(--text-dim);font-size:0.85rem;margin:8px 0 16px">Aktualisiere den Pico W kabellos direkt über GitHub oder flashe einzelne Dateien.</p>\n    \n    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem">\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <h4 style="color:var(--accent);margin-bottom:8px">1. GitHub OTA Update</h4>\n        <p style="font-size:0.8rem;color:var(--text-dim);margin-bottom:12px">Lädt den neuesten Stand des Haupt-Branches von GitHub herunter und startet neu.</p>\n        <button class="btn" onclick="triggerGitHubOTA()" id="btn-ota">Jetzt von GitHub aktualisieren</button>\n        <div id="ota-status" style="font-size:0.8rem;margin-top:8px;color:var(--amber)"></div>\n      </div>\n\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <h4 style="color:var(--accent);margin-bottom:8px">2. Firmware-Datei (Flash)</h4>\n        <p style="font-size:0.8rem;color:var(--text-dim);margin-bottom:12px">Lade eine geänderte Python-Datei (.py) direkt in das Flash-Dateisystem des Pico hoch.</p>\n        <input type="file" id="file-upload-input" accept=".py" style="font-size:0.8rem;margin-bottom:8px;color:var(--text-dim)">\n        <button class="btn btn-amber" onclick="uploadFile()">Datei flashen</button>\n        <div id="upload-status" style="font-size:0.8rem;margin-top:8px;color:var(--green)"></div>\n      </div>\n\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <h4 style="color:var(--accent);margin-bottom:8px">3. Geräte-Konfiguration (Backup & Restore)</h4>\n        <p style="font-size:0.8rem;color:var(--text-dim);margin-bottom:10px">Sichere alle bekannten Geräte oder lade ein devices.json Backup wieder zurück.</p>\n        <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px">\n          <a href="/api/devices/download" download="devices.json" class="btn" style="text-decoration:none;display:inline-block">💾 Download</a>\n        </div>\n        <div style="border-top:1px solid rgba(255,255,255,0.06);padding-top:8px">\n          <label style="font-size:0.75rem;color:var(--text-dim)">devices.json wiederherstellen:</label>\n          <input type="file" id="devices-upload-input" accept=".json" style="font-size:0.8rem;margin:6px 0;color:var(--text-dim);display:block">\n          <button class="btn btn-amber" onclick="uploadDevicesJson()">Wiederherstellen</button>\n          <div id="devices-upload-status" style="font-size:0.8rem;margin-top:6px;color:var(--green)"></div>\n        </div>\n      </div>\n\n      <div style="background:rgba(15,23,42,0.6);border:1px solid var(--border);padding:1rem;border-radius:10px">\n        <h4 style="color:var(--red);margin-bottom:8px">4. Gateway Neustart (Reboot)</h4>\n        <p style="font-size:0.8rem;color:var(--text-dim);margin-bottom:12px">Führt einen Software-Warmstart des Raspberry Pi Pico W durch, um geänderte Programmdateien neu einzulesen.</p>\n        <button class="btn btn-del" onclick="rebootGateway()" id="btn-reboot">🔄 Pico W neu starten</button>\n        <div id="reboot-status" style="font-size:0.8rem;margin-top:8px;color:var(--amber)"></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- Modal für generisches Sensor-Anlernen & Konfiguration -->\n<div id="config-modal" class="modal">\n  <div class="modal-card" style="max-width:500px">\n    <h3 id="cfg-modal-title" style="margin-bottom:8px">⚙ Sensor anlernen & konfigurieren</h3>\n    <div id="cfg-modal-info" style="background:rgba(255,255,255,0.05);padding:8px;border-radius:6px;font-size:0.85rem;margin-bottom:12px"></div>\n    \n    <label style="font-size:0.8rem;color:var(--text-dim)">Gerätename (identisch in signalrpi & Home Assistant):</label>\n    <input id="cfg-name" class="form-input" type="text" placeholder="z.B. kueche2 oder ferdi" oninput="onCfgNameInput()" style="margin-bottom:4px">\n    <div style="font-size:0.75rem;color:var(--text-dim);margin-bottom:12px">ID / Topic: <code id="cfg-ha-id-preview" style="color:var(--accent)">-</code></div>\n    \n    <label style="font-size:0.8rem;color:var(--text-dim)">Gerätetyp / Funktion:</label>\n    <select id="cfg-type-select" class="form-input" style="margin-bottom:12px" onchange="onCfgTypeChange()">\n      <option value="switch">🔌 Funk-Schalter</option>\n      <option value="light">💡 Licht / Lampe</option>\n      <option value="button">🔘 Fernbedienung / Taster</option>\n      <option value="contact">🚪 Tür- / Fensterkontakt</option>\n      <option value="thermo_hygro">🌡 Temperatur- & Feuchtesensor</option>\n      <option value="thermo">🌡 Nur Temperatursensor</option>\n      <option value="rain">🌧 Regensensor</option>\n      <option value="moisture">🌱 Bodenfeuchtesensor</option>\n      <option value="sensor">📊 Allgemeiner Mess-Sensor</option>\n    </select>\n    \n    <div id="cfg-entities-container">\n      <label style="font-size:0.8rem;color:var(--text-dim)">Erkannte Messwerte / Entitäten:</label>\n      <div id="cfg-entities-list" style="margin:8px 0 16px;display:flex;flex-direction:column;gap:8px"></div>\n    </div>\n    \n    <input type="hidden" id="cfg-edit-id" value="">\n\n    <div style="display:flex;justify-content:flex-end;gap:8px">\n      <button class="btn" style="background:#64748b;color:#fff" onclick="closeConfigModal()">Abbrechen</button>\n      <button class="btn" onclick="saveConfiguredDevice()">Speichern</button>\n    </div>\n  </div>\n</div>\n\n<!-- Modal für Batteriewechsel / Neu-Zuordnung -->\n<div id="reassign-modal" class="modal">\n  <div class="modal-card">\n    <h3 style="margin-bottom:8px">Sensor neu zuordnen</h3>\n    <p style="color:var(--text-dim);font-size:0.85rem;margin-bottom:12px">Wähle das bestehende Home Assistant Gerät aus, dem diese neue ID nach einem Batteriewechsel zugewiesen werden soll:</p>\n    <div id="modal-info" style="background:rgba(255,255,255,0.05);padding:8px;border-radius:6px;font-size:0.85rem;margin-bottom:12px"></div>\n    <label style="font-size:0.85rem;color:var(--text-dim)">Bestehendes Gerät:</label>\n    <select id="modal-select" class="form-input"></select>\n    <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:1rem">\n      <button class="btn" style="background:#64748b;color:#fff" onclick="closeModal()">Abbrechen</button>\n      <button class="btn btn-amber" onclick="executeReassign()">Zuordnen</button>\n    </div>\n  </div>\n</div>\n\n<!-- Modal für Rohdaten-Inspektor / Signal-Export -->\n<div id="raw-modal" class="modal">\n  <div class="modal-card" style="max-width:540px">\n    <h3 style="margin-bottom:8px">🔬 Signal-Rohdaten & Export</h3>\n    <div id="raw-modal-meta" style="font-size:0.85rem;color:var(--text-dim);margin-bottom:10px"></div>\n    <label style="font-size:0.8rem;color:var(--text-dim)">Pulsfolge / Rohdaten:</label>\n    <textarea id="raw-modal-text" style="width:100%;height:150px;background:rgba(15,23,42,0.9);color:#38bdf8;border:1px solid var(--border);border-radius:6px;padding:8px;font-family:monospace;font-size:0.75rem;margin:6px 0 12px;resize:vertical" readonly></textarea>\n    <div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between">\n      <div style="display:flex;gap:6px">\n        <button class="btn" onclick="copyRaw(\'json\')">📋 JSON kopieren</button>\n        <button class="btn btn-amber" onclick="copyRaw(\'text\')">📋 SignalESP/FHEM</button>\n      </div>\n      <button class="btn" style="background:#64748b;color:#fff" onclick="closeRawModal()">Schließen</button>\n    </div>\n  </div>\n</div>\n\n<div id="toast-container" class="toast-container"></div>\n\n<script>\nlet knownDevices = [];\nlet pendingReassign = null;\nlet currentRawData = null;\n\nfunction showToast(msg, type=\'success\'){\n  let container = document.getElementById(\'toast-container\');\n  if(!container) return;\n  let toast = document.createElement(\'div\');\n  toast.className = \'toast toast-\' + type;\n  let icon = type === \'success\' ? \'✔\' : (type === \'error\' ? \'✖\' : \'ℹ\');\n  toast.innerHTML = `<span style="font-weight:700">${icon}</span> <span>${msg}</span>`;\n  container.appendChild(toast);\n  setTimeout(()=>{\n    toast.style.opacity = \'0\';\n    toast.style.transform = \'translateY(12px)\';\n    setTimeout(()=> toast.remove(), 300);\n  }, 3200);\n}\n\nfunction showTab(tabId){\n  document.querySelectorAll(\'.tab-content\').forEach(el=>el.style.display=\'none\');\n  document.querySelectorAll(\'.nav > .nav-btn\').forEach(el=>el.classList.remove(\'active\'));\n  let targetTab = document.getElementById(tabId);\n  if(targetTab) targetTab.style.display=\'block\';\n  let targetNavBtn = document.querySelector(`.nav > button[onclick*="\'${tabId}\'"]`);\n  if(targetNavBtn) targetNavBtn.classList.add(\'active\');\n  // Sniffer nur aktiv wenn Tab sichtbar (verhindert stilles Leeren der Queue)\n  snifferActive = (tabId === \'tab-sniffer\');\n}\n\nasync function refreshDevices(){\n  try{\n    let res = await fetch(\'/api/devices\');\n    knownDevices = await res.json();\n    renderDevices();\n  }catch(e){}\n}\n\nfunction renderDeviceCard(d){\n  let isEn = d.enabled !== false;\n  let mqttBadge = isEn \n    ? `<span style="background:rgba(34,197,94,0.15);color:#22c55e;border:1px solid rgba(34,197,94,0.3);padding:2px 8px;border-radius:12px;font-size:0.75rem;font-weight:600">MQTT</span>`\n    : \'\';\n\n  let currentProf = d.profile || (d.type === \'switch\' ? \'switch\' : (d.type === \'light\' ? \'light\' : (d.entities && d.entities.length > 2 ? \'thermo_hygro\' : (d.entities && d.entities.some(e=>e.key===\'state\') ? (d.protocol===\'IT\'?\'button\':\'contact\') : \'thermo\'))));\n  let isActuator = (d.type === \'switch\' || d.type === \'light\' || currentProf === \'switch\' || currentProf === \'light\');\n  let infoLine = \'\';\n  if(d.protocol === \'IT_V3\' && d.binary_code){\n    infoLine = `HA-ID: <code>${d.id}</code> | Code: <b style="font-family:monospace">${d.binary_code}</b> | Ch: <b>${d.channel||1}</b>`;\n  } else if(d.protocol === \'IT\' && d.it_code){\n    infoLine = `HA-ID: <code>${d.id}</code> | Hauscode: <b>${d.it_code.family}</b> | Gruppe: <b>${d.it_code.group}</b> | Kanal: <b>${d.it_code.device}</b>`;\n  } else {\n    infoLine = `HA-ID: <code>${d.id}</code> | Funk-ID: <b>${d.device_id||\'Auto\'}</b> ${d.channel?\'| Kanal: \'+d.channel:\'\'}`;\n  }\n\n  return `\n    <div class="device-card" style="cursor:pointer;transition:border-color 0.2s" onclick="editDevice(\'${d.id}\')" title="Klicken zum Bearbeiten">\n      <div style="display:flex;justify-content:space-between;align-items:center">\n        <strong style="font-size:1.05rem">${d.name} <span style="font-size:0.8rem;color:var(--text-dim);font-weight:normal">✏</span></strong>\n        <div style="display:flex;gap:6px;align-items:center">\n          ${mqttBadge}\n          <span style="font-size:0.75rem;color:var(--accent);font-weight:600">${d.protocol}</span>\n        </div>\n      </div>\n      <div style="font-size:0.8rem;color:var(--text-dim);margin:6px 0">\n        ${infoLine}\n      </div>\n      <div class="val-grid">\n        ${(d.entities||[]).filter(e => e.key !== \'channel\' && e.key !== \'forced_send\').map(e=>{\n          let val = (d.latest && d.latest[e.key] !== undefined) ? d.latest[e.key] : (d.last_values ? d.last_values[e.key] : null);\n          return `\n            <div class="val-box">\n              <div class="val-title">${e.name}</div>\n              <div class="val-num">${val!==null && val!==undefined ? val+(e.unit?\' \'+e.unit:\'\') : \'--\'}</div>\n            </div>\n          `;\n        }).join(\'\')}\n        ${isActuator ? `\n          <div class="val-box">\n            <div class="val-title">${d.type===\'light\'?\'Lichtzustand\':\'Schaltzustand\'}</div>\n            <div class="val-num">${(d.latest && d.latest.state) ? d.latest.state : \'OFF\'}</div>\n          </div>\n          <div class="val-box">\n            <div class="val-title">Wdh (Reps)</div>\n            <div class="val-num">${d.repetitions || 6}</div>\n          </div>\n        ` : \'\'}\n      </div>\n      ${isActuator ? `\n        <div style="display:flex;gap:6px;margin:8px 0" onclick="event.stopPropagation()">\n          <button class="btn" style="flex:1;background:var(--accent);color:#0f172a" onclick="sendDeviceSwitch(\'${d.id}\',\'on\')">EIN</button>\n          <button class="btn" style="flex:1;background:var(--red);color:#fff" onclick="sendDeviceSwitch(\'${d.id}\',\'off\')">AUS</button>\n        </div>\n      ` : \'\'}\n      <div style="font-size:0.75rem;color:var(--text-dim);margin-bottom:10px">\n        ${isActuator ? \'Letzter Befehl: \' : \'Empfang: \'}<b>${(d.latest && d.latest._time) ? d.latest._time : (d.last_seen ? new Date(d.last_seen*1000).toLocaleTimeString() : \'Warte auf Signal...\')}</b>\n      </div>\n      <!-- Funktionsleiste am unteren Rand -->\n      <div style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:6px;padding-top:8px;border-top:1px solid rgba(255,255,255,0.06)" onclick="event.stopPropagation()">\n        <select class="form-input" style="width:auto;margin:0;padding:4px 6px;font-size:0.75rem" onchange="changeDeviceProfile(\'${d.id}\', this.value)">\n          <option value="switch" ${currentProf===\'switch\'?\'selected\':\'\'}>🔌 Schalter</option>\n          <option value="light" ${currentProf===\'light\'?\'selected\':\'\'}>💡 Licht / Lampe</option>\n          <option value="button" ${currentProf===\'button\'?\'selected\':\'\'}>🔘 Fernbedienung / Taster</option>\n          <option value="contact" ${currentProf===\'contact\'?\'selected\':\'\'}>🚪 Tür-/Fensterkontakt</option>\n          <option value="thermo_hygro" ${currentProf===\'thermo_hygro\'?\'selected\':\'\'}>🌡 Temp + Feuchte</option>\n          <option value="thermo" ${currentProf===\'thermo\'?\'selected\':\'\'}>🌡 Nur Temperatur</option>\n          <option value="rain" ${currentProf===\'rain\'?\'selected\':\'\'}>🌧 Regensensor</option>\n          <option value="moisture" ${currentProf===\'moisture\'?\'selected\':\'\'}>🌱 Bodenfeuchte</option>\n        </select>\n        <div style="display:flex;gap:6px">\n          <button class="btn ${isEn ? \'btn-amber\' : \'\'}" style="padding:4px 10px;font-size:0.75rem" onclick="toggleDevice(\'${d.id}\')">\n            ${isEn ? \'📡 MQTT deregistrieren\' : \'📡 MQTT registrieren\'}\n          </button>\n          <button class="btn btn-del" style="padding:4px 8px;font-size:0.75rem" onclick="deleteDevice(\'${d.id}\')">🗑 Löschen</button>\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderDevices(){\n  let c = document.getElementById(\'devices-list\');\n  if(!c) return;\n  if(!knownDevices || !knownDevices.length){\n    c.innerHTML = \'<p style="color:var(--text-dim)">Keine Geräte angelegt.</p>\';\n    return;\n  }\n\n  // 1. Filter anwenden\n  let filterMqtt = document.getElementById(\'device-filter-mqtt\') ? document.getElementById(\'device-filter-mqtt\').value : \'all\';\n  let filtered = knownDevices.filter(d => {\n    let isEn = d.enabled !== false;\n    if(filterMqtt === \'mqtt_only\') return isEn;\n    if(filterMqtt === \'no_mqtt\') return !isEn;\n    return true;\n  });\n\n  if(!filtered.length){\n    c.innerHTML = \'<p style="color:var(--text-dim)">Keine Geräte entsprechen dem gewählten Filter.</p>\';\n    return;\n  }\n\n  // 2. Alphabetisch nach Name sortieren (A..Z)\n  filtered.sort((a, b) => (a.name || a.id || \'\').localeCompare(b.name || b.id || \'\', undefined, {sensitivity: \'base\', numeric: true}));\n\n  // 3. Gruppierung ermitteln\n  let grpMode = document.getElementById(\'device-grouping-select\') ? document.getElementById(\'device-grouping-select\').value : \'none\';\n\n  if(grpMode === \'none\'){\n    c.innerHTML = `<div class="grid">${filtered.map(renderDeviceCard).join(\'\')}</div>`;\n    return;\n  }\n\n  // Helper für Profil-Labels\n  let profNames = {\n    switch: \'🔌 Funk-Schalter\',\n    light: \'💡 Funk-Lichter & Lampen\',\n    button: \'🔘 Fernbedienungen & Taster\',\n    contact: \'🚪 Tür- & Fensterkontakte\',\n    thermo_hygro: \'🌡 Temperatur- & Feuchtesensoren\',\n    thermo: \'🌡 Temperatur-Sensoren\',\n    rain: \'🌧 Regensensoren\',\n    moisture: \'🌱 Bodenfeuchte-Sensoren\',\n    sensor: \'📊 Allgemeine Sensoren\'\n  };\n\n  let groups = {};\n  filtered.forEach(d => {\n    let key = \'\';\n    let title = \'\';\n    if(grpMode === \'protocol\'){\n      key = d.protocol || \'Unbekannt\';\n      title = \'📻 Protokoll: \' + key;\n    } else if(grpMode === \'profile\'){\n      let prof = d.profile || (d.type === \'switch\' ? \'switch\' : (d.type === \'light\' ? \'light\' : (d.entities && d.entities.length > 2 ? \'thermo_hygro\' : (d.entities && d.entities.some(e=>e.key===\'state\') ? (d.protocol===\'IT\'?\'button\':\'contact\') : \'thermo\'))));\n      key = prof;\n      title = profNames[prof] || (\'Typ: \' + prof);\n    } else if(grpMode === \'mqtt\'){\n      let isEn = d.enabled !== false;\n      key = isEn ? \'mqtt_active\' : \'mqtt_inactive\';\n      title = isEn ? \'📡 Home Assistant MQTT aktiv\' : \'💤 Lokal / Ohne MQTT\';\n    }\n    if(!groups[key]) groups[key] = {title: title, list: []};\n    groups[key].list.push(d);\n  });\n\n  let groupKeys = Object.keys(groups).sort();\n  // Bei MQTT bevorzugt \'mqtt_active\' zuerst anzeigen\n  if(grpMode === \'mqtt\'){\n    groupKeys.sort((a,b) => (a === \'mqtt_active\' ? -1 : 1));\n  }\n\n  c.innerHTML = groupKeys.map(k => {\n    let grp = groups[k];\n    return `\n      <div style="margin-bottom:1.5rem">\n        <div style="display:flex;align-items:center;gap:8px;margin-bottom:0.75rem;padding-bottom:4px;border-bottom:1px solid rgba(255,255,255,0.08)">\n          <h4 style="color:var(--accent);font-size:0.95rem;margin:0">${grp.title}</h4>\n          <span style="font-size:0.75rem;background:rgba(255,255,255,0.08);padding:1px 7px;border-radius:10px;color:var(--text-dim)">${grp.list.length}</span>\n        </div>\n        <div class="grid">\n          ${grp.list.map(renderDeviceCard).join(\'\')}\n        </div>\n      </div>\n    `;\n  }).join(\'\');\n}\n\nfunction editDevice(id){\n  let dev = (knownDevices || []).find(d => d.id === id);\n  if(!dev) return;\n\n  if(dev.protocol === \'IT_V3\'){\n    showTab(\'tab-it\');\n    switchITType(\'v3\');\n    document.getElementById(\'it-v3-edit-id\').value = dev.id;\n    document.getElementById(\'it-v3-name\').value = dev.name || \'\';\n    document.getElementById(\'it-v3-bin\').value = dev.binary_code || dev.device_id || \'\';\n    document.getElementById(\'it-v3-channel\').value = dev.channel || 1;\n    document.getElementById(\'it-v3-reps\').value = dev.repetitions || 6;\n    validateITV3Bits();\n    document.getElementById(\'it-v3-save-btn\').innerText = \'💾 Aktualisieren\';\n    document.getElementById(\'it-v3-cancel-btn\').style.display = \'inline-block\';\n    document.getElementById(\'it-v3-name\').scrollIntoView({behavior: \'smooth\'});\n  } else if(dev.protocol === \'IT\'){\n    showTab(\'tab-it\');\n    switchITType(\'v1\');\n    let itc = dev.it_code || {};\n    document.getElementById(\'it-v1-edit-id\').value = dev.id;\n    document.getElementById(\'it-name\').value = dev.name || \'\';\n    document.getElementById(\'it-family\').value = itc.family || \'A\';\n    document.getElementById(\'it-group\').value = itc.group || 1;\n    document.getElementById(\'it-device\').value = itc.device || 1;\n    document.getElementById(\'it-v1-reps\').value = dev.repetitions || 6;\n    document.getElementById(\'it-v1-save-btn\').innerText = \'💾 Aktualisieren\';\n    document.getElementById(\'it-v1-cancel-btn\').style.display = \'inline-block\';\n    document.getElementById(\'it-name\').scrollIntoView({behavior: \'smooth\'});\n  } else {\n    // Sensor Gerät bearbeiten\n    openEditSensorModal(dev);\n  }\n}\n\nfunction resetITV3Form(){\n  document.getElementById(\'it-v3-edit-id\').value = \'\';\n  document.getElementById(\'it-v3-name\').value = \'Küche Stehlampe\';\n  document.getElementById(\'it-v3-channel\').value = 1;\n  document.getElementById(\'it-v3-reps\').value = 6;\n  document.getElementById(\'it-v3-save-btn\').innerText = \'💾 Anlegen\';\n  document.getElementById(\'it-v3-cancel-btn\').style.display = \'none\';\n  generateUniqueITV3Code();\n}\n\nfunction resetITV1Form(){\n  document.getElementById(\'it-v1-edit-id\').value = \'\';\n  document.getElementById(\'it-name\').value = \'Stehlampe\';\n  document.getElementById(\'it-family\').value = \'E\';\n  document.getElementById(\'it-group\').value = 1;\n  document.getElementById(\'it-device\').value = 4;\n  document.getElementById(\'it-v1-reps\').value = 6;\n  document.getElementById(\'it-v1-save-btn\').innerText = \'💾 Anlegen\';\n  document.getElementById(\'it-v1-cancel-btn\').style.display = \'none\';\n}\n\nfunction sanitizeDeviceName(str){\n  if(!str) return \'\';\n  return str\n    .replace(/ä/g, \'ae\').replace(/Ä/g, \'ae\')\n    .replace(/ö/g, \'oe\').replace(/Ö/g, \'oe\')\n    .replace(/ü/g, \'ue\').replace(/Ü/g, \'ue\')\n    .replace(/ß/g, \'ss\')\n    .replace(/[^a-zA-Z0-9_-]/g, \'_\')\n    .replace(/_+/g, \'_\')\n    .toLowerCase();\n}\n\nfunction onCfgNameInput(){\n  let input = document.getElementById(\'cfg-name\');\n  let clean = sanitizeDeviceName(input.value);\n  let preview = document.getElementById(\'cfg-ha-id-preview\');\n  if(preview) preview.innerText = clean || \'-\';\n}\n\nfunction openEditSensorModal(dev){\n  pendingAdoptPacket = {\n    proto: dev.protocol,\n    id: dev.device_id,\n    channel: dev.channel,\n    isEdit: true,\n    editDev: dev\n  };\n  document.getElementById(\'cfg-edit-id\').value = dev.id;\n  document.getElementById(\'cfg-modal-title\').innerText = \'⚙ Sensor bearbeiten\';\n  document.getElementById(\'cfg-modal-info\').innerHTML = `\n    <b>Protokoll:</b> ${dev.protocol} | <b>Funk-ID:</b> <code>${dev.device_id}</code> ${dev.channel ? \'| <b>Kanal:</b> \'+dev.channel : \'\'}\n  `;\n  document.getElementById(\'cfg-name\').value = dev.name || dev.id;\n  onCfgNameInput();\n  let typeSel = document.getElementById(\'cfg-type-select\');\n  if(typeSel){\n    typeSel.value = dev.profile || (dev.type === \'switch\' ? \'switch\' : (dev.type === \'light\' ? \'light\' : (dev.protocol === \'IT\' ? \'button\' : \'sensor\')));\n  }\n  onCfgTypeChange();\n\n  let listEl = document.getElementById(\'cfg-entities-list\');\n  listEl.innerHTML = \'\';\n\n  let ents = dev.entities || [];\n  if(!ents.length){\n    ents = [{key: \'temperature\', name: \'Temperatur\', unit: \'°C\', device_class: \'temperature\'}];\n  }\n\n  ents.forEach(e=>{\n    let row = document.createElement(\'div\');\n    row.className = \'cfg-ent-row\';\n    row.style = \'display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.02);padding:6px;border-radius:6px;border:1px solid rgba(255,255,255,0.05)\';\n    row.innerHTML = `\n      <input type="checkbox" class="ent-enable" data-key="${e.key}" checked style="width:16px;height:16px">\n      <input class="form-input ent-name" value="${e.name||e.key}" style="margin:0;padding:4px 6px;flex:2;font-size:0.8rem">\n      <input class="form-input ent-unit" value="${e.unit||\'\'}" placeholder="Einheit" style="margin:0;padding:4px 6px;flex:1;font-size:0.8rem">\n      <select class="form-input ent-class" style="margin:0;padding:4px 6px;flex:1.5;font-size:0.8rem">\n        <option value="temperature" ${e.device_class===\'temperature\'?\'selected\':\'\'}>Temperatur</option>\n        <option value="humidity" ${e.device_class===\'humidity\'?\'selected\':\'\'}>Luftfeuchtigkeit</option>\n        <option value="moisture" ${e.device_class===\'moisture\'?\'selected\':\'\'}>Bodenfeuchtigkeit</option>\n        <option value="precipitation" ${e.device_class===\'precipitation\'?\'selected\':\'\'}>Regenmenge</option>\n        <option value="battery" ${e.device_class===\'battery\'?\'selected\':\'\'}>Batterie</option>\n        <option value="voltage" ${e.device_class===\'voltage\'?\'selected\':\'\'}>Spannung (V)</option>\n        <option value="wind_speed" ${e.device_class===\'wind_speed\'?\'selected\':\'\'}>Wind</option>\n        <option value="door" ${e.device_class===\'door\'?\'selected\':\'\'}>Kontakt</option>\n        <option value="sensor" ${(!e.device_class||e.device_class===\'sensor\')?\'selected\':\'\'}>Allgemein</option>\n      </select>\n    `;\n    listEl.appendChild(row);\n  });\n\n  document.getElementById(\'config-modal\').style.display = \'flex\';\n}\n\nasync function changeDeviceProfile(id, profile){\n  try{\n    await fetch(\'/api/devices/profile\', {\n      method: \'POST\',\n      body: JSON.stringify({id: id, profile: profile})\n    });\n    refreshDevices();\n  }catch(e){}\n}\n\nasync function toggleDevice(id){\n  try{\n    let res = await fetch(\'/api/devices/toggle\', {\n      method: \'POST\',\n      body: JSON.stringify({id: id})\n    });\n    refreshDevices();\n  }catch(e){}\n}\n\nasync function delDevice(id){\n  if(confirm(\'Gerät \'+id+\' wirklich löschen?\')){\n    await fetch(\'/api/devices?id=\'+id, {method:\'DELETE\'});\n    refreshDevices();\n  }\n}\n\nfunction deleteDevice(id){\n  return delDevice(id);\n}\n\nasync function updateSystem(){\n  try{\n    let res = await fetch(\'/api/status\');\n    let s = await res.json();\n    if(s.time) document.getElementById(\'s-time\').innerText = s.time;\n    document.getElementById(\'s-ip\').innerText = s.ip;\n    document.getElementById(\'s-rssi\').innerText = s.wifi_rssi+\' dBm\';\n    document.getElementById(\'s-ram\').innerText = Math.round(s.free_ram/1024)+\' kB\';\n    \n    // 1. Modul 1 (433 MHz) Status\n    let b4 = document.getElementById(\'badge-cc433\');\n    let cb4 = document.getElementById(\'cc433-badge\');\n    let cd4 = document.getElementById(\'cc433-details\');\n    if(s.cc_433){\n      let c4 = s.cc_433;\n      let stText = c4.ok ? \'433 MHz: OK\' : \'433 MHz: FEHLER\';\n      let pillBg = c4.ok ? \'rgba(34,197,94,0.2)\' : \'rgba(239,68,68,0.2)\';\n      let pillColor = c4.ok ? \'var(--green)\' : \'var(--red)\';\n      if(b4){ b4.innerText = stText; b4.style.background = pillBg; b4.style.color = pillColor; }\n      if(cb4){ cb4.innerText = c4.state_name || (c4.ok ? \'OK\' : \'FEHLER\'); cb4.style.background = pillBg; cb4.style.color = pillColor; }\n      if(cd4){\n        cd4.innerHTML = \'<b>Status:</b> \' + c4.msg + \'<br>\' +\n                        \'<b>Frequenz:</b> \' + (c4.freq || 433.92) + \' MHz (\' + (c4.mode || \'OOK\') + \')<br>\' +\n                        \'<b>Chip:</b> Part 0x\' + (c4.partnum !== undefined ? c4.partnum.toString(16).toUpperCase() : \'??\') + \' / Version 0x\' + (c4.version !== undefined ? c4.version.toString(16).toUpperCase() : \'??\');\n      }\n    } else {\n      if(b4){ b4.innerText = \'433 MHz: Aktiv\'; b4.style.background = \'rgba(34,197,94,0.2)\'; b4.style.color = \'var(--green)\'; }\n      if(cb4){ cb4.innerText = \'Aktiv\'; cb4.style.background = \'rgba(34,197,94,0.2)\'; cb4.style.color = \'var(--green)\'; }\n      if(cd4){ cd4.innerHTML = \'<b>Status:</b> Aktiv (Empfang läuft)<br><b>Frequenz:</b> 433.92 MHz (OOK)\'; }\n    }\n    \n    // 2. Modul 2 (868 MHz) Status\n    let b8 = document.getElementById(\'badge-cc868\');\n    let cb8 = document.getElementById(\'cc868-badge\');\n    let cd8 = document.getElementById(\'cc868-details\');\n    if(s.cc_868){\n      let c8 = s.cc_868;\n      let stText8 = c8.ok ? \'868 MHz: OK\' : \'868 MHz: FEHLER\';\n      let pillBg8 = c8.ok ? \'rgba(34,197,94,0.2)\' : \'rgba(239,68,68,0.2)\';\n      let pillColor8 = c8.ok ? \'var(--green)\' : \'var(--red)\';\n      if(b8){ b8.innerText = stText8; b8.style.background = pillBg8; b8.style.color = pillColor8; }\n      if(cb8){ cb8.innerText = c8.state_name || (c8.ok ? \'OK\' : \'FEHLER\'); cb8.style.background = pillBg8; cb8.style.color = pillColor8; }\n      if(cd8){\n        cd8.innerHTML = \'<b>Status:</b> \' + c8.msg + \'<br>\' +\n                        \'<b>Frequenz:</b> \' + (c8.freq || 868.35) + \' MHz (\' + (c8.mode || \'FSK\') + \')<br>\' +\n                        \'<b>Chip:</b> Part 0x\' + (c8.partnum !== undefined ? c8.partnum.toString(16).toUpperCase() : \'??\') + \' / Version 0x\' + (c8.version !== undefined ? c8.version.toString(16).toUpperCase() : \'??\');\n      }\n    } else {\n      if(b8){ b8.innerText = \'868 MHz: Warte auf Reboot\'; b8.style.background = \'rgba(245,158,11,0.2)\'; b8.style.color = \'var(--amber)\'; }\n      if(cb8){ cb8.innerText = \'Warte auf Reboot\'; cb8.style.background = \'rgba(245,158,11,0.2)\'; cb8.style.color = \'var(--amber)\'; }\n      if(cd8){ cd8.innerHTML = \'<b>Status:</b> Python-Backend erfordert Neustart für SPI-Hardwaretest<br><b>Frequenz:</b> 868.35 MHz (FSK)\'; }\n    }\n    \n    // 3. System Alerts\n    if(s.alerts && s.alerts.length > 0){\n      let alertBox = document.getElementById(\'system-alerts-list\');\n      if(alertBox){\n        alertBox.innerHTML = s.alerts.map(a => {\n          let col = a.level === \'error\' ? \'var(--red)\' : (a.level === \'warning\' ? \'var(--amber)\' : \'var(--accent)\');\n          return \'<div style="margin-bottom:4px;border-bottom:1px solid rgba(255,255,255,0.04);padding-bottom:2px"><span style="color:var(--text-dim)">[\' + a.time + \']</span> <b style="color:\' + col + \'">[\' + a.level.toUpperCase() + \']</b> \' + a.msg + \'</div>\';\n        }).reverse().join(\'\');\n      }\n    }\n  }catch(e){}\n}\n\nasync function loadTimeSettings(){\n  try{\n    let res = await fetch(\'/api/time\');\n    let cfg = await res.json();\n    if(cfg.tz_offset !== undefined) document.getElementById(\'tz-offset\').value = cfg.tz_offset;\n    if(cfg.auto_dst !== undefined) document.getElementById(\'tz-auto-dst\').checked = cfg.auto_dst;\n    if(cfg.custom_ntp) document.getElementById(\'tz-server\').value = cfg.custom_ntp;\n  }catch(e){}\n}\n\nasync function saveTimeSettings(){\n  let offset = parseInt(document.getElementById(\'tz-offset\').value);\n  let autoDst = document.getElementById(\'tz-auto-dst\').checked;\n  let customNtp = document.getElementById(\'tz-server\').value.trim();\n  let st = document.getElementById(\'tz-status\');\n  st.innerText = \'Synchronisiere...\';\n  try{\n    let res = await fetch(\'/api/time\', {\n      method: \'POST\',\n      body: JSON.stringify({tz_offset: offset, auto_dst: autoDst, custom_ntp: customNtp})\n    });\n    let r = await res.json();\n    if(r.ok && r.time){\n      st.innerText = \'✔ \' + r.time + \' (\' + (r.server||\'NTP\') + \')\';\n      updateSystem();\n      refreshDevices();\n    } else {\n      st.innerText = \'Fehler beim Synchronisieren\';\n    }\n  }catch(e){\n    st.innerText = \'Fehler: \' + e;\n  }\n}\n\nlet snifferActive = true;\nlet snifferStarted = false;\n\nfunction toggleSniffer(){\n  let btn = document.getElementById(\'sniffer-toggle-btn\');\n  snifferActive = !snifferActive;\n  if(btn){\n    btn.innerText = snifferActive ? \'Pausieren\' : \'Starten\';\n    btn.className = snifferActive ? \'btn btn-amber\' : \'btn\';\n  }\n}\n\nfunction onCfgTypeChange(){\n  let t = document.getElementById(\'cfg-type-select\').value;\n  let cont = document.getElementById(\'cfg-entities-container\');\n  if(cont){\n    cont.style.display = (t === \'switch\') ? \'none\' : \'block\';\n  }\n}\n\nfunction startSniffer(){\n  if(snifferStarted) return;\n  snifferStarted = true;\n  let s = document.getElementById(\'sniffer-list\');\n  let btn = document.getElementById(\'sniffer-toggle-btn\');\n  if(btn){\n    btn.innerText = \'Pausieren\';\n    btn.className = \'btn btn-amber\';\n  }\n  let poll = async ()=>{\n    if(!snifferActive){ setTimeout(poll, 2000); return; }\n    try{\n      let r = await fetch(\'/api/live\');\n      let pkts = await r.json();\n      pkts.forEach(p=>{\n        let div = document.createElement(\'div\');\n        div.className = \'packet\';\n        \n        // Prüfe ob Gerät bereits bekannt ist (entweder durch matched_name vom Backend oder Abgleich mit knownDevices)\n        let matchedDev = (knownDevices || []).find(d => {\n          if(d.protocol !== p.proto) return false;\n          if(p.channel && d.channel && String(d.channel) !== String(p.channel)) return false;\n          return String(d.device_id) === String(p.id);\n        });\n        let devName = p.device_name || (matchedDev ? matchedDev.name : null);\n        let devBadge = devName ? `<span style="background:rgba(34,197,94,0.2);color:var(--green);padding:2px 8px;border-radius:12px;font-weight:600;font-size:0.75rem;margin-left:6px">✔ ${devName}</span>` : \'\';\n        let dataStr = Object.entries(p.data||{}).map(([k,v])=>`${k}: <b>${v}</b>`).join(\' | \');\n        \n        let rawBtn = p.raw ? `<button class="btn" style="background:#475569;color:#fff" onclick=\'openRawModal(${JSON.stringify(p)})\'>🔬 Rohdaten</button>` : \'\';\n        \n        let actionBtns = \'\';\n        if(p.proto!==\'RAW_433\' && p.proto!==\'RAW_868_OOK\' && p.proto!==\'RAW_868_FSK\'){\n          if(matchedDev){\n            actionBtns = `<button class="btn" style="background:#334155;color:#fff" onclick="editDevice(\'${matchedDev.id}\')">✏ Bearbeiten</button>`;\n          } else {\n            actionBtns = `\n              <button class="btn btn-amber" onclick="openReassign(\'${p.proto}\',\'${p.id}\',\'${p.channel||\'\'}\')">Zuordnen</button>\n              <button class="btn" onclick=\'openAdoptModal(${JSON.stringify(p)})\'>Neu anlernen</button>\n            `;\n          }\n        }\n\n        div.innerHTML = `\n          <div>\n            <span style="color:var(--text-dim)">[${p.time}]</span> \n            <span style="color:var(--accent);font-weight:700">[${p.band}]</span> \n            <b>${p.proto}</b> \n            (ID: <code>${p.id}</code>${p.channel?\' Ch:\'+p.channel:\'\'}) \n            ${devBadge}\n            <span style="background:rgba(255,255,255,0.08);padding:2px 6px;border-radius:4px;font-size:0.75rem;margin-left:4px">${p.rssi} dBm</span>\n            <div style="font-size:0.8rem;color:var(--text-dim);margin-top:4px">${dataStr||(p.raw ? \'Rohsignal (\'+(Array.isArray(p.raw)?p.raw.length+\' Pulse\':p.raw.length+\' Zeichen\')+\')\' : \'Rohdaten\')}</div>\n          </div>\n          <div style="display:flex;gap:6px">\n            ${rawBtn}\n            ${actionBtns}\n          </div>\n        `;\n        s.insertBefore(div, s.firstChild);\n        if(s.children.length>50) s.removeChild(s.lastChild);\n      });\n    }catch(e){}\n    setTimeout(poll, 1500);\n  };\n  poll();\n}\n\nfunction openRawModal(pkt){\n  currentRawData = pkt;\n  let isArr = Array.isArray(pkt.raw);\n  let countInfo = isArr ? `${pkt.raw.length} Flanken / Pulse` : `${pkt.raw.length} Zeichen (Hex-Stream)`;\n  document.getElementById(\'raw-modal-meta\').innerHTML = `\n    <b>Band:</b> ${pkt.band} | <b>Signal:</b> ${pkt.proto} | <b>RSSI:</b> ${pkt.rssi} dBm | <b>Länge:</b> ${countInfo}\n  `;\n  let ta = document.getElementById(\'raw-modal-text\');\n  if(isArr){\n    ta.value = JSON.stringify(pkt.raw);\n  } else {\n    ta.value = pkt.raw || \'\';\n  }\n  document.getElementById(\'raw-modal\').style.display = \'flex\';\n}\n\nfunction closeRawModal(){\n  document.getElementById(\'raw-modal\').style.display = \'none\';\n  currentRawData = null;\n}\n\nfunction copyRaw(fmt){\n  if(!currentRawData || !currentRawData.raw) return;\n  let txt = \'\';\n  if(fmt === \'json\'){\n    txt = JSON.stringify(currentRawData.raw);\n  } else if(fmt === \'text\'){\n    if(Array.isArray(currentRawData.raw)){\n      txt = currentRawData.raw.map(v => (v > 0 ? \'+\' : \'\') + v).join(\' \');\n    } else {\n      txt = currentRawData.raw;\n    }\n  }\n  navigator.clipboard.writeText(txt).then(()=>{\n    showToast(\'In die Zwischenablage kopiert (\' + fmt.toUpperCase() + \')!\');\n  }).catch(()=>{\n    prompt(\'Kopieren fehlgeschlagen. Hier manuell kopieren:\', txt);\n  });\n}\n\nfunction openAdoptModal(pkt){\n  pendingAdoptPacket = pkt;\n  document.getElementById(\'cfg-modal-info\').innerHTML = `\n    <b>Protokoll:</b> ${pkt.proto} | <b>Funk-ID:</b> <code>${pkt.id}</code> ${pkt.channel ? \'| <b>Kanal:</b> \'+pkt.channel : \'\'}\n  `;\n  document.getElementById(\'cfg-name\').value = pkt.proto + \' \' + pkt.id;\n  document.getElementById(\'cfg-edit-id\').value = \'\';\n  onCfgNameInput();\n\n  // Typ-Vorbelegung anhand des Protokolls und der erkannten Daten\n  let typeSel = document.getElementById(\'cfg-type-select\');\n  if(pkt.proto === \'IT\' || pkt.proto === \'IT_V3\'){\n    typeSel.value = \'switch\';\n  } else if(pkt.proto === \'SD_WS_126\' || (pkt.data && (pkt.data.rain_total !== undefined || pkt.data.rain_ticks !== undefined))){\n    typeSel.value = \'rain\';\n  } else if(pkt.proto === \'SD_WS_107\' || pkt.proto === \'SD_WS_50\' || (pkt.data && pkt.data.moisture !== undefined)){\n    typeSel.value = \'moisture\';\n  } else if(pkt.data && pkt.data.temperature !== undefined && pkt.data.humidity !== undefined){\n    typeSel.value = \'thermo_hygro\';\n  } else if(pkt.data && pkt.data.temperature !== undefined){\n    typeSel.value = \'thermo\';\n  } else {\n    typeSel.value = \'sensor\';\n  }\n  onCfgTypeChange();\n  \n  // Dynamische Entitätenerkennung aus pkt.data\n  let listEl = document.getElementById(\'cfg-entities-list\');\n  listEl.innerHTML = \'\';\n  \n  let entries = Object.entries(pkt.data || {}).filter(([k,v]) => k !== \'channel\' && k !== \'forced_send\');\n  if(!entries.length){\n    entries = [[\'state\', \'1\']];\n  }\n  \n  entries.forEach(([key, val])=>{\n    let unit = \'\';\n    let devClass = \'sensor\';\n    let defName = key;\n    \n    if(key === \'temperature\') { unit = \'°C\'; devClass = \'temperature\'; defName = \'Temperatur\'; }\n    else if(key === \'humidity\') { unit = \'%\'; devClass = \'humidity\'; defName = \'Luftfeuchtigkeit\'; }\n    else if(key === \'battery_low\') { unit = \'\'; devClass = \'battery\'; defName = \'Batterie Status\'; }\n    else if(key === \'battery_voltage\') { unit = \'V\'; devClass = \'voltage\'; defName = \'Batteriespannung\'; }\n    else if(key === \'moisture\') { unit = \'%\'; devClass = \'moisture\'; defName = \'Bodenfeuchtigkeit\'; }\n    else if(key === \'rain_total\' || key === \'rain\') { unit = \'mm\'; devClass = \'precipitation\'; defName = \'Regenmenge\'; }\n    else if(key === \'rain_ticks\') { unit = \'\'; devClass = \'sensor\'; defName = \'Wippenschläge\'; }\n    else if(key === \'adc\') { unit = \'\'; devClass = \'sensor\'; defName = \'ADC Wert\'; }\n    else if(key === \'wind_speed\') { unit = \'km/h\'; devClass = \'wind_speed\'; defName = \'Windgeschwindigkeit\'; }\n    else if(key === \'state\') { unit = \'\'; devClass = (pkt.proto===\'IT\'?\'button\':\'door\'); defName = (pkt.proto===\'IT\'?\'Taste / Zustand\':\'Kontakt Status\'); }\n    \n    let row = document.createElement(\'div\');\n    row.className = \'cfg-ent-row\';\n    row.style = \'display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.02);padding:6px;border-radius:6px;border:1px solid rgba(255,255,255,0.05)\';\n    row.innerHTML = `\n      <input type="checkbox" class="ent-enable" data-key="${key}" checked style="width:16px;height:16px">\n      <input class="form-input ent-name" value="${defName}" style="margin:0;padding:4px 6px;flex:2;font-size:0.8rem">\n      <input class="form-input ent-unit" value="${unit}" placeholder="Einheit" style="margin:0;padding:4px 6px;flex:1;font-size:0.8rem">\n      <select class="form-input ent-class" style="margin:0;padding:4px 6px;flex:1.5;font-size:0.8rem">\n        <option value="switch" ${devClass===\'switch\'?\'selected\':\'\'}>Schalter</option>\n        <option value="button" ${devClass===\'button\'?\'selected\':\'\'}>Taste (Fernbedienung)</option>\n        <option value="door" ${devClass===\'door\'?\'selected\':\'\'}>Kontakt (Tür/Fenster)</option>\n        <option value="temperature" ${devClass===\'temperature\'?\'selected\':\'\'}>Temperatur</option>\n        <option value="humidity" ${devClass===\'humidity\'?\'selected\':\'\'}>Luftfeuchtigkeit</option>\n        <option value="moisture" ${devClass===\'moisture\'?\'selected\':\'\'}>Bodenfeuchtigkeit</option>\n        <option value="precipitation" ${devClass===\'precipitation\'?\'selected\':\'\'}>Regenmenge</option>\n        <option value="battery" ${devClass===\'battery\'?\'selected\':\'\'}>Batterie</option>\n        <option value="voltage" ${devClass===\'voltage\'?\'selected\':\'\'}>Spannung (V)</option>\n        <option value="wind_speed" ${devClass===\'wind_speed\'?\'selected\':\'\'}>Wind</option>\n        <option value="sensor" ${devClass===\'sensor\'?\'selected\':\'\'}>Allgemein</option>\n      </select>\n    `;\n    listEl.appendChild(row);\n  });\n  \n  document.getElementById(\'config-modal\').style.display = \'flex\';\n}\n\nfunction closeConfigModal(){\n  document.getElementById(\'config-modal\').style.display = \'none\';\n  pendingAdoptPacket = null;\n}\n\nasync function saveConfiguredDevice(){\n  if(!pendingAdoptPacket) return;\n  let rawName = document.getElementById(\'cfg-name\').value.trim();\n  if(!rawName) { showToast(\'Bitte einen Namen angeben\', \'error\'); return; }\n  \n  // Sonderzeichen bereinigen: Name und ID sind identisch ohne Sonderzeichen\n  let cleanName = sanitizeDeviceName(rawName);\n  let safeId = cleanName;\n\n  let editId = document.getElementById(\'cfg-edit-id\').value.trim();\n  let existingDev = editId ? (knownDevices || []).find(d => d.id === editId) : null;\n\n  // Falls sich die ID geändert hat (Umbenennung), altes Gerät und alte HA-Topics sauber entfernen\n  if(editId && editId !== safeId){\n    try {\n      await fetch(\'/api/devices?id=\' + encodeURIComponent(editId), {method: \'DELETE\'});\n    } catch(e){}\n  }\n  \n  let isEnabled = existingDev ? (existingDev.enabled !== false) : false;\n  let selectedType = document.getElementById(\'cfg-type-select\').value;\n  \n  let isActuatorType = (selectedType === \'switch\' || selectedType === \'light\');\n  let entities = [];\n  if(!isActuatorType){\n    document.querySelectorAll(\'.cfg-ent-row\').forEach(row=>{\n      let cb = row.querySelector(\'.ent-enable\');\n      if(cb && cb.checked){\n        let key = cb.getAttribute(\'data-key\');\n        let entName = row.querySelector(\'.ent-name\').value.trim() || key;\n        let unit = row.querySelector(\'.ent-unit\').value.trim();\n        let cls = row.querySelector(\'.ent-class\').value;\n        let entObj = {key: key, name: entName, device_class: cls};\n        if(unit) entObj.unit = unit;\n        if(cls === \'button\') entObj.icon = \'mdi:remote\';\n        entities.push(entObj);\n      }\n    });\n  }\n  \n  let payload = {\n    id: safeId,\n    name: cleanName,\n    protocol: pendingAdoptPacket.proto,\n    device_id: pendingAdoptPacket.id,\n    channel: pendingAdoptPacket.channel ? parseInt(pendingAdoptPacket.channel) : null,\n    type: isActuatorType ? selectedType : \'sensor\',\n    profile: selectedType,\n    enabled: isEnabled,\n    entities: entities\n  };\n\n  if(isActuatorType){\n    payload.repetitions = existingDev ? (existingDev.repetitions || 6) : 6;\n    payload.icon = (selectedType === \'light\') ? \'mdi:lightbulb\' : \'mdi:power-socket-de\';\n    if(pendingAdoptPacket.proto === \'IT\'){\n      let parts = String(pendingAdoptPacket.id).split(\'_\');\n      let fam = parts[0] || \'A\';\n      let grp = parseInt(parts[1]) || 1;\n      let devNum = parseInt(parts[2]) || 1;\n      payload.it_code = {family: fam, group: grp, device: devNum};\n    } else if(pendingAdoptPacket.proto === \'IT_V3\'){\n      payload.binary_code = pendingAdoptPacket.id;\n      payload.channel = pendingAdoptPacket.channel || 1;\n    }\n  }\n  \n  await fetch(\'/api/devices\', {\n    method: \'POST\',\n    body: JSON.stringify(payload)\n  });\n  \n  closeConfigModal();\n  refreshDevices();\n  showToast(\'Gerät "\' + cleanName + \'" erfolgreich \' + (editId ? \'aktualisiert\' : \'angelegt\') + (isEnabled ? \' (MQTT aktiv)\' : \'\'));\n}\n\nfunction openReassign(proto, id, ch){\n  pendingReassign = {proto: proto, new_id: id, channel: ch?parseInt(ch):null};\n  document.getElementById(\'modal-info\').innerHTML = `Neues Signal: <b>${proto}</b> | Neue Funk-ID: <code>${id}</code> ${ch?\'(Kanal \'+ch+\')\':\'\'}`;\n  let sel = document.getElementById(\'modal-select\');\n  sel.innerHTML = knownDevices.map(d=>`<option value="${d.id}">${d.name} (${d.id})</option>`).join(\'\');\n  document.getElementById(\'reassign-modal\').style.display = \'flex\';\n}\n\nfunction closeModal(){\n  document.getElementById(\'reassign-modal\').style.display = \'none\';\n  pendingReassign = null;\n}\n\nasync function executeReassign(){\n  if(!pendingReassign) return;\n  let ha_id = document.getElementById(\'modal-select\').value;\n  await fetch(\'/api/reassign\', {\n    method: \'POST\',\n    body: JSON.stringify({ha_id: ha_id, new_id: pendingReassign.new_id, channel: pendingReassign.channel})\n  });\n  closeModal();\n  refreshDevices();\n  showToast(\'Funk-ID erfolgreich aktualisiert!\');\n}\n\nfunction switchITSubTab(type){\n  try {\n    let btnV3 = document.getElementById(\'it-tab-btn-v3\');\n    let btnV1 = document.getElementById(\'it-tab-btn-v1\');\n    let formV3 = document.getElementById(\'it-form-v3\');\n    let formV1 = document.getElementById(\'it-form-v1\');\n    if(!formV3 || !formV1) return;\n    if(type === \'v3\'){\n      formV3.style.display = \'block\';\n      formV1.style.display = \'none\';\n      if(btnV3){\n        btnV3.style.background = \'var(--accent)\';\n        btnV3.style.color = \'#0f172a\';\n        btnV3.style.border = \'none\';\n      }\n      if(btnV1){\n        btnV1.style.background = \'transparent\';\n        btnV1.style.color = \'var(--text-dim)\';\n        btnV1.style.border = \'1px solid var(--border)\';\n      }\n    } else {\n      formV3.style.display = \'none\';\n      formV1.style.display = \'block\';\n      if(btnV1){\n        btnV1.style.background = \'var(--accent)\';\n        btnV1.style.color = \'#0f172a\';\n        btnV1.style.border = \'none\';\n      }\n      if(btnV3){\n        btnV3.style.background = \'transparent\';\n        btnV3.style.color = \'var(--text-dim)\';\n        btnV3.style.border = \'1px solid var(--border)\';\n      }\n    }\n  } catch(e) {\n    console.error(\'switchITSubTab error:\', e);\n  }\n}\nwindow.switchITSubTab = switchITSubTab;\nwindow.switchITType = switchITSubTab;\n\nfunction validateITV3Bits(){\n  let input = document.getElementById(\'it-v3-bin\');\n  let raw = input.value.trim();\n  let parts = raw.split(/[ ]+/);\n\n  // Falls der Nutzer einen String wie \'00011100110111100110100111 0 0000\' eingibt:\n  if(parts.length >= 3 && parts[0].length === 26 && parts[2].length === 4){\n    let binCode = parts[0].replace(/[^01]/g, \'\');\n    let unitBits = parts[2].replace(/[^01]/g, \'\');\n    let unitNum = parseInt(unitBits, 2) + 1; // 0000 -> Kanal 1\n    input.value = binCode;\n    let chInput = document.getElementById(\'it-v3-channel\');\n    if(chInput) chInput.value = unitNum;\n  } else {\n    let clean = input.value.replace(/[^01]/g, \'\').slice(0, 26);\n    if(input.value !== clean) input.value = clean;\n  }\n\n  let cleanVal = input.value.replace(/[^01]/g, \'\');\n  let counter = document.getElementById(\'it-v3-bitcount\');\n  counter.innerText = cleanVal.length + \' / 26 Bit\';\n  counter.style.color = (cleanVal.length === 26) ? \'var(--green)\' : \'var(--accent)\';\n}\n\nfunction generateUniqueITV3Code(){\n  // Extrahiere bereits verwendete V3-Codes aus knownDevices\n  let usedCodes = new Set();\n  (knownDevices || []).forEach(d => {\n    if(d.binary_code) usedCodes.add(d.binary_code);\n    if(d.it_v3 && d.it_v3.binary_code) usedCodes.add(d.it_v3.binary_code);\n  });\n\n  let newCode = \'\';\n  let attempts = 0;\n  do {\n    newCode = \'\';\n    for(let i = 0; i < 26; i++){\n      newCode += (Math.random() > 0.5 ? \'1\' : \'0\');\n    }\n    attempts++;\n  } while (usedCodes.has(newCode) && attempts < 1000);\n\n  let input = document.getElementById(\'it-v3-bin\');\n  input.value = newCode;\n  validateITV3Bits();\n}\n\nasync function saveITV3Device(){\n  let rawName = document.getElementById(\'it-v3-name\').value.trim();\n  if(!rawName){ showToast(\'Bitte einen Gerätenamen angeben\', \'error\'); return; }\n  let cleanName = sanitizeDeviceName(rawName);\n  let safeId = cleanName;\n\n  let binInput = document.getElementById(\'it-v3-bin\').value.trim().replace(/[^01]/g, \'\');\n  if(binInput.length !== 26){\n    showToast(\'Intertechno V3 Code muss 26 Bit lang sein (aktuell \' + binInput.length + \')\', \'error\');\n    return;\n  }\n\n  let channel = parseInt(document.getElementById(\'it-v3-channel\').value) || 1;\n  let reps = parseInt(document.getElementById(\'it-v3-reps\').value) || 6;\n\n  let editId = document.getElementById(\'it-v3-edit-id\').value.trim();\n  let existingDev = editId ? (knownDevices || []).find(d => d.id === editId) : null;\n\n  if(editId && editId !== safeId){\n    try {\n      await fetch(\'/api/devices?id=\' + encodeURIComponent(editId), {method: \'DELETE\'});\n    } catch(e){}\n  }\n\n  let isEnabled = existingDev ? (existingDev.enabled !== false) : false;\n\n  let payload = {\n    id: safeId,\n    name: cleanName,\n    protocol: \'IT_V3\',\n    type: \'switch\',\n    binary_code: binInput,\n    device_id: binInput,\n    channel: channel,\n    repetitions: reps,\n    icon: \'mdi:power-socket-de\',\n    enabled: isEnabled\n  };\n\n  try {\n    let res = await fetch(\'/api/devices\', {\n      method: \'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify(payload)\n    });\n    if(res.ok){\n      resetITV3Form();\n      refreshDevices();\n      showToast(\'Intertechno V3 Gerät "\' + cleanName + \'" \' + (editId ? \'aktualisiert\' : \'angelegt\') + (isEnabled ? \' (MQTT aktiv)\' : \'\'), \'success\');\n    } else {\n      showToast(\'Fehler beim Speichern (HTTP \' + res.status + \')\', \'error\');\n    }\n  } catch(e) {\n    showToast(\'Netzwerkfehler: \' + e, \'error\');\n  }\n}\n\nasync function sendITV3Command(action){\n  let bin = document.getElementById(\'it-v3-bin\').value.trim().replace(/[^01]/g, \'\');\n  if(bin.length !== 26){\n    showToast(\'Bitte zuerst einen gültigen 26-Bit Code eingeben!\', \'error\');\n    return;\n  }\n  let ch = parseInt(document.getElementById(\'it-v3-channel\').value) || 1;\n  let reps = parseInt(document.getElementById(\'it-v3-reps\').value) || 6;\n  try {\n    let r = await fetch(\'/api/it/send\', {\n      method: \'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify({\n        protocol: \'IT_V3\',\n        action: action,\n        binary_code: bin,\n        channel: ch,\n        repetitions: reps\n      })\n    });\n    let res = await r.json();\n    if(res.ok){\n      if(action === \'learn\'){\n        showToast(\'📡 Anlernsignal gesendet (Code: \' + bin + \', Ch: \' + ch + \')\', \'success\');\n      } else {\n        showToast(\'Befehl \' + action.toUpperCase() + \' an Intertechno V3 gesendet\', \'success\');\n      }\n    } else {\n      showToast(\'Fehler beim Senden: \' + (res.error || \'Unbekannt\'), \'error\');\n    }\n  } catch(e) {\n    showToast(\'Netzwerkfehler beim Senden: \' + e, \'error\');\n  }\n}\n\nasync function sendITV1Command(action){\n  let fam = document.getElementById(\'it-family\').value.toUpperCase();\n  let grp = parseInt(document.getElementById(\'it-group\').value) || 1;\n  let dev = parseInt(document.getElementById(\'it-device\').value) || 1;\n  let reps = parseInt(document.getElementById(\'it-v1-reps\').value) || 6;\n  try {\n    let r = await fetch(\'/api/it/send\', {\n      method: \'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify({\n        protocol: \'IT_V1\',\n        action: action,\n        family: fam,\n        group: grp,\n        device: dev,\n        repetitions: reps\n      })\n    });\n    let res = await r.json();\n    if(res.ok){\n      showToast(\'Befehl \' + action.toUpperCase() + \' an Intertechno V1 (\' + fam + grp + dev + \') gesendet\', \'success\');\n    } else {\n      showToast(\'Fehler beim Senden: \' + (res.error || \'Unbekannt\'), \'error\');\n    }\n  } catch(e) {\n    showToast(\'Netzwerkfehler beim Senden: \' + e, \'error\');\n  }\n}\n\nasync function sendDeviceSwitch(id, action){\n  let dev = (knownDevices || []).find(d => d.id === id);\n  if(!dev) return;\n  let reps = dev.repetitions || 6;\n  let payload = { action: action, repetitions: reps };\n  if(dev.protocol === \'IT_V3\'){\n    payload.protocol = \'IT_V3\';\n    payload.binary_code = dev.binary_code || dev.device_id;\n    payload.channel = dev.channel || 1;\n  } else {\n    payload.protocol = \'IT_V1\';\n    let itc = dev.it_code || {};\n    payload.family = itc.family || \'A\';\n    payload.group = itc.group || 1;\n    payload.device = itc.device || 1;\n  }\n  try {\n    let r = await fetch(\'/api/it/send\', {\n      method: \'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify(payload)\n    });\n    let res = await r.json();\n    if(res.ok){\n      showToast(dev.name + \' -> \' + action.toUpperCase(), \'success\');\n      refreshDevices();\n    } else {\n      showToast(\'Fehler beim Schalten\', \'error\');\n    }\n  } catch(e) {\n    showToast(\'Fehler: \' + e, \'error\');\n  }\n}\n\nasync function saveITDevice(){\n  let rawName = document.getElementById(\'it-name\').value.trim();\n  if(!rawName){ showToast(\'Bitte einen Gerätenamen angeben\', \'error\'); return; }\n  let cleanName = sanitizeDeviceName(rawName);\n  let safeId = cleanName;\n  let fam = document.getElementById(\'it-family\').value.toUpperCase();\n  let grp = parseInt(document.getElementById(\'it-group\').value) || 1;\n  let dev = parseInt(document.getElementById(\'it-device\').value) || 1;\n  let reps = parseInt(document.getElementById(\'it-v1-reps\').value) || 6;\n\n  let editId = document.getElementById(\'it-v1-edit-id\').value.trim();\n  let existingDev = editId ? (knownDevices || []).find(d => d.id === editId) : null;\n\n  if(editId && editId !== safeId){\n    try {\n      await fetch(\'/api/devices?id=\' + encodeURIComponent(editId), {method: \'DELETE\'});\n    } catch(e){}\n  }\n\n  let isEnabled = existingDev ? (existingDev.enabled !== false) : false;\n\n  try {\n    let res = await fetch(\'/api/devices\', {\n      method:\'POST\',\n      headers: {\'Content-Type\': \'application/json\'},\n      body: JSON.stringify({\n        id: safeId, \n        name: cleanName, \n        protocol:\'IT\', \n        type:\'switch\', \n        device_id: fam + \'_\' + grp + \'_\' + dev,\n        it_code:{family:fam, group:grp, device:dev}, \n        repetitions: reps,\n        icon:\'mdi:power-socket-de\', \n        enabled: isEnabled\n      })\n    });\n    if(res.ok){\n      resetITV1Form();\n      refreshDevices();\n      showToast(\'Intertechno V1 Schalter "\' + cleanName + \'" \' + (editId ? \'aktualisiert\' : \'angelegt\') + (isEnabled ? \' (MQTT aktiv)\' : \'\'), \'success\');\n    } else {\n      showToast(\'Fehler beim Speichern (HTTP \' + res.status + \')\', \'error\');\n    }\n  } catch(e) {\n    showToast(\'Netzwerkfehler: \' + e, \'error\');\n  }\n}\n\nasync function triggerGitHubOTA(){\n  if(!confirm(\'GitHub OTA Update jetzt starten? Der Pico lädt die Dateien herunter und startet neu.\')) return;\n  let btn = document.getElementById(\'btn-ota\');\n  let st = document.getElementById(\'ota-status\');\n  btn.disabled = true;\n  st.innerText = \'OTA Download läuft... Bitte ca. 10 Sekunden warten.\';\n  try{\n    await fetch(\'/api/ota\', {method:\'POST\'});\n    st.innerText = \'Pico startet neu... Verbinde in 5s neu...\';\n    setTimeout(()=>{ location.reload(); }, 6000);\n  }catch(e){\n    st.innerText = \'Fehler beim Auslösen des OTA Updates.\';\n    btn.disabled = false;\n  }\n}\n\nasync function rebootGateway(){\n  if(!confirm(\'Raspberry Pi Pico W jetzt neu starten?\')) return;\n  let btn = document.getElementById(\'btn-reboot\');\n  let st = document.getElementById(\'reboot-status\');\n  btn.disabled = true;\n  st.innerText = \'Neustart wird ausgeführt... Verbinde in 5s neu...\';\n  try{\n    await fetch(\'/api/restart\', {method:\'POST\'});\n  }catch(e){}\n  setTimeout(()=>{ location.reload(); }, 5000);\n}\n\nasync function uploadFile(){\n  let input = document.getElementById(\'file-upload-input\');\n  let st = document.getElementById(\'upload-status\');\n  if(!input.files || !input.files[0]){\n    showToast(\'Bitte zuerst eine Datei auswählen!\', \'error\');\n    return;\n  }\n  let file = input.files[0];\n  st.innerText = \'Lade \' + file.name + \' hoch...\';\n  try{\n    let reader = new FileReader();\n    reader.onload = async function(e){\n      let content = e.target.result;\n      let res = await fetch(\'/api/upload?filename=\'+encodeURIComponent(file.name), {\n        method: \'POST\',\n        body: content\n      });\n      if(res.ok){\n        st.innerText = \'Datei \' + file.name + \' erfolgreich geflasht!\';\n        showToast(\'Datei \' + file.name + \' erfolgreich hochgeladen!\');\n      } else {\n        st.innerText = \'Fehler beim Hochladen.\';\n        showToast(\'Fehler beim Hochladen\', \'error\');\n      }\n    };\n    reader.readAsArrayBuffer(file);\n  }catch(e){\n    st.innerText = \'Upload fehlgeschlagen: \' + e;\n    showToast(\'Upload fehlgeschlagen\', \'error\');\n  }\n}\n\nasync function uploadDevicesJson(){\n  let input = document.getElementById(\'devices-upload-input\');\n  let st = document.getElementById(\'devices-upload-status\');\n  if(!input.files || !input.files[0]){\n    showToast(\'Bitte zuerst eine devices.json Datei auswählen!\', \'error\');\n    return;\n  }\n  let file = input.files[0];\n  if(!file.name.endsWith(\'.json\')){\n    showToast(\'Bitte eine gültige .json Datei auswählen!\', \'error\');\n    return;\n  }\n  st.innerText = \'Lade Geräte-Konfiguration hoch...\';\n  try{\n    let reader = new FileReader();\n    reader.onload = async function(e){\n      let text = e.target.result;\n      try{\n        JSON.parse(text); // Validierungsprüfung\n      }catch(err){\n        showToast(\'Ungültiges JSON-Format! Abbruch.\', \'error\');\n        st.innerText = \'Fehler: Ungültiges JSON\';\n        return;\n      }\n      let res = await fetch(\'/api/upload?filename=devices.json\', {\n        method: \'POST\',\n        body: text\n      });\n      if(res.ok){\n        st.innerText = \'Geräte erfolgreich wiederhergestellt & geladen!\';\n        refreshDevices();\n        showToast(\'Geräte-Konfiguration erfolgreich wiederhergestellt!\');\n      } else {\n        st.innerText = \'Fehler beim Wiederherstellen.\';\n        showToast(\'Fehler beim Wiederherstellen\', \'error\');\n      }\n    };\n    reader.readAsText(file);\n  }catch(e){\n    st.innerText = \'Upload fehlgeschlagen: \' + e;\n    showToast(\'Upload fehlgeschlagen\', \'error\');\n  }\n}\n\nrefreshDevices();\nupdateSystem();\nloadTimeSettings();\nstartSniffer();\nsetInterval(updateSystem, 8000);\nsetInterval(refreshDevices, 5000);\n</script>\n</body>\n</html>\n'
